import std.io

pub type AppError = Failed(String)

newtype Name(String)

fn echo(s: String) -> String {
    return s
}

fn label(n: Name) -> String {
    n = n
    return n.value
}

pub fn main() effect io -> Result<(), AppError> {
    let a = "x${1}y"
    a = "A"
    io.println(a)

    let b = "l" + "r"
    b = "B"
    io.println(b)

    let c = echo("hi")
    c = "C"
    io.println(c)

    io.println(label(Name("t")))
    return Ok(())
}
